// The launcher and WDIO worker load this file separately. Pass the selected
// ports through the inherited environment so both use the same pair.
const reservePort = (): Promise<number> => new Promise((resolve, reject) => {
  const server = net.createServer();
  server.once('error', reject);
  server.listen(0, '127.0.0.1', () => {
    const address = server.address();
    if (!address || typeof address === 'string') {
      server.close();
      reject(new Error('could not reserve native WebDriver port'));
      return;
    }
    server.close((error) => error ? reject(error) : resolve(address.port));
  });
});

if (!process.env.STARTUP_EXPERIMENT_DRIVER_PORT) {
  process.env.STARTUP_EXPERIMENT_DRIVER_PORT = String(await reservePort());
  process.env.STARTUP_EXPERIMENT_NATIVE_PORT = String(await reservePort());
}
const driverPort = Number(process.env.STARTUP_EXPERIMENT_DRIVER_PORT);
const nativePort = Number(process.env.STARTUP_EXPERIMENT_NATIVE_PORT);
if (!Number.isSafeInteger(driverPort) || !Number.isSafeInteger(nativePort) ||
    driverPort <= 0 || nativePort <= 0 || driverPort === nativePort) {
  throw new Error('invalid isolated WebDriver port pair');
}

const report = process.env.STARTUP_EXPERIMENT_REPORT;
if (!report) throw new Error('STARTUP_EXPERIMENT_REPORT is required');
const driverGroupFile = `${report}.driver-group`;
const driverLogFile = `${report}.driver.log`;

const waitForPort = async (port: number, timeoutMs: number): Promise<void> => {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const connected = await new Promise<boolean>((resolve) => {
      const socket = net.connect(port, '127.0.0.1');
      socket.once('connect', () => { socket.destroy(); resolve(true); });
      socket.once('error', () => resolve(false));
    });
    if (connected) return;
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
  throw new Error(`tauri-driver did not listen on isolated port ${port}`);
};

const stopDriverGroup = async (): Promise<void> => {
