import { measureProcessTreeRss, type NativeProcessRow } from './native-qualification';
function rss(): number {
  const rows: NativeProcessRow[] = [];
  for (const id of fs.readdirSync('/proc')) {
    if (!/^\d+$/.test(id)) continue;
    try {
      const stat = fs.readFileSync(`/proc/${id}/stat`, 'utf8').split(') ').at(-1)!.split(' ');
      const status = fs.readFileSync(`/proc/${id}/status`, 'utf8');
      rows.push({ pid: Number(id), parentPid: Number(stat[1]), executable: fs.readlinkSync(`/proc/${id}/exe`), rssBytes: Number(status.match(/VmRSS:\s+(\d+)/)?.[1] ?? 0)*1024 });
    } catch {}
  }
  return measureProcessTreeRss(rows, process.env.STARTUP_EXPERIMENT_BINARY!, Date.now()).rssBytes;
}


